#include <iostream>
#include <vector>
#include <iomanip>

int main() {
    // Dimensions: A is m x n, B is n x p -> C is m x p
    int m = 0, n = 0, p = 0;
    if (!(std::cin >> m >> n >> p) || m <= 0 || n <= 0 || p <= 0) {
        return 0;
    }

    std::vector<std::vector<double>> A(m, std::vector<double>(n));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            std::cin >> A[i][j];
        }
    }

    std::vector<std::vector<double>> B(n, std::vector<double>(p));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < p; ++j) {
            std::cin >> B[i][j];
        }
    }

    // Matrix multiplication: C[i][j] = sum_k(A[i][k] * B[k][j])
    std::vector<std::vector<double>> C(m, std::vector<double>(p, 0.0));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < p; ++j) {
            double sum = 0.0;
            for (int k = 0; k < n; ++k) {
                sum += A[i][k] * B[k][j];
            }
            C[i][j] = sum;
        }
    }

    // Output formatted result
    std::cout << "Result Matrix:" << '\n';
    std::cout << std::fixed << std::setprecision(2);
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < p; ++j) {
            std::cout << std::setw(8) << C[i][j];
        }
        std::cout << '\n';
    }

    return 0;
}

