void trace_behavior(int n, int x, int y) {
    std::cout << "Input: n=" << n << ", x=" << x << ", y=" << y << " -> ";

    // Exact textbook structure: else binds to inner if
    if (n % 2 == 0) 
        if (x > 3) 
            x = 0;
        else 
            y = 0;

    std::cout << "Result: x=" << x << ", y=" << y << '\n';
}

