}

#include <iostream>
#include <iomanip>
#include <cmath>

// Exercise 24b: Compute exp(x) via Taylor series until term < 1e-6
double exp_taylor(double x, double eps = 1e-6) {
    double sum = 1.0;
    double term = 1.0;
    int n = 1;
    while (std::abs(term) >= eps) {
        term *= (x / n);
        sum += term;
        ++n;
    }
    return sum;
}

// Exercise 26a: Bisection method for f(x) = exp(x) - 1.5 on [0, 1]
double solve_bisection(double a, double b, double eps = 1e-6) {
    auto f = [](double x) { return std::exp(x) - 1.5; };
    double mid = a;
    while ((b - a) / 2.0 >= eps) {
        mid = a + (b - a) / 2.0;
        if (f(mid) == 0.0) break;
        if (f(a) * f(mid) < 0) {
            b = mid;
        } else {
            a = mid;
        }
    }
    return a + (b - a) / 2.0;
}

int main() {
    double x = 1.0;
    double my_exp = exp_taylor(x);
    double root = solve_bisection(0.0, 1.0);

    std::cout << std::fixed << std::setprecision(6);
    std::cout << "exp(1.0) approx: " << my_exp << '\n';
    std::cout << "Root of exp(x)-1.5=0: " << root << '\n';
    std::cout << "Verification exp(root): " << std::exp(root) << '\n';
    return 0;
}
